private static List<StrokePathInfo> tracePaths(
        char[][] grid,
        Map<GridPoint, List<GridPoint>> adjacency,
        Map<GridEdge, Boolean> dashedEdges) {
    Set<GridEdge> remaining = new HashSet<>(dashedEdges.keySet());
    List<StrokePathInfo> paths = new ArrayList<>();

    List<GridPoint> startNodes = new ArrayList<>();
    for (Map.Entry<GridPoint, List<GridPoint>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() != 2) {
            startNodes.add(entry.getKey());
        }
    }
    startNodes.sort(Comparator.comparingInt((GridPoint p) -> p.y).thenComparingInt(p -> p.x));

    for (GridPoint start : startNodes) {
        List<GridPoint> neighbors = adjacency.getOrDefault(start, Collections.emptyList());
        for (GridPoint next : neighbors) {
            GridEdge edge = new GridEdge(start, next);
            if (!remaining.contains(edge)) {
                continue;
            }
            paths.add(traceOnePath(grid, adjacency, dashedEdges, remaining, start, next));
        }
    }

    while (!remaining.isEmpty()) {
        GridEdge edge = remaining.iterator().next();
        paths.add(traceOnePath(grid, adjacency, dashedEdges, remaining, edge.a, edge.b));
    }

    return paths;
}

private static StrokePathInfo traceOnePath(
        char[][] grid,
        Map<GridPoint, List<GridPoint>> adjacency,
        Map<GridEdge, Boolean> dashedEdges,
        Set<GridEdge> remaining,
        GridPoint start,
        GridPoint next) {
    List<GridPoint> points = new ArrayList<>();
    points.add(start);
    boolean dashed = false;
    GridPoint prev = start;
    GridPoint curr = next;
    ArrowDir arrowStart = arrowFor(grid, start, next);

    while (true) {
        GridEdge edge = new GridEdge(prev, curr);
        remaining.remove(edge);
        dashed |= dashedEdges.getOrDefault(edge, false);
        points.add(curr);

        List<GridPoint> neighbors = adjacency.getOrDefault(curr, Collections.emptyList());
        List<GridPoint> candidates = new ArrayList<>();
        for (GridPoint candidate : neighbors) {
            if (candidate.equals(prev)) {
                continue;
            }
            if (remaining.contains(new GridEdge(curr, candidate))) {
                candidates.add(candidate);
            }
        }
        if (candidates.size() != 1) {
            break;
        }
        prev = curr;
        curr = candidates.get(0);
        if (curr.equals(start)) {
            GridEdge closing = new GridEdge(prev, curr);
            remaining.remove(closing);
            dashed |= dashedEdges.getOrDefault(closing, false);
            points.add(curr);
            break;
        }
    }

