                    circlePath(layout.bulletX, layout.baseline - layout.bulletRadius, layout.bulletRadius));
            appendf(
                    out,
                    "    <text x='%.1f' y='%.1f' font-family='%s' font-size='%d' stroke='none' fill='%s'>%s</text>\n",
                    layout.x,
                    layout.baseline,
                    layout.fontFamily,
                    layout.fontSize,
                    shape.textColor.hexRgb(),
                    cdata(layout.text));
        } else {
            appendf(
                    out,
                    "    <text x='%.1f' y='%.1f' font-family='%s' font-size='%d' stroke='none' fill='%s'>%s</text>\n",
                    layout.x,
                    layout.baseline,
                    layout.fontFamily,
                    layout.fontSize,
                    shape.textColor.hexRgb(),
                    cdata(layout.text));
        }
    }
}

private static void renderSvgLooseText(StringBuilder out, LooseText text, CliOptions options) {
    String family = options.svgFontUrl != null ? "Custom" : "Courier";
    TextMetrics metrics = measureAndFit(text.text, (pxX(text.end, options.scale) - pxX(text.start, options.scale)),
            family, BASE_FONT_SIZE);
    double centerX = (pxX(text.start, options.scale) + pxX(text.end, options.scale)) / 2.0;
    double baseline = pxY(text.row, options.scale) + metrics.baselineOffset();
    double x = centerX - metrics.width / 2.0;
    appendf(
            out,
            "    <text x='%.1f' y='%.1f' font-family='%s' font-size='%d' stroke='none' fill='#000000'>%s</text>\n",
            x,
            baseline,
            family,
            metrics.fontSize,
            cdata(text.text));
}

private static List<TextLayout> layoutShapeText(DiagramShape shape, double scale, String family) {
    List<TextLayout> layouts = new ArrayList<>();
    if (shape.textLines.isEmpty()) {
        return layouts;
    }
    double left = pxX(shape.x0, scale);
    double right = pxX(shape.x1, scale);
    double top = pxY(shape.y0, scale);
    double bottom = pxY(shape.y1, scale);
    double centerX = (left + right) / 2.0;
    double textWidth = Math.max(16.0 * scale, right - left - 16.0 * scale);

    for (TextEntry line : shape.textLines) {
        TextMetrics metrics = measureAndFit(line.text, textWidth, family, BASE_FONT_SIZE);
        double baseline = pxY(shape.y0 + 1 + line.rowOffset, scale) + metrics.baselineOffset();
        if (line.bullet) {
            double bulletX = left + 18.0 * scale;
            double textX = left + 28.0 * scale;
            layouts.add(new TextLayout(line.text, true, metrics.fontSize, family, textX, baseline,
                    bulletX, 3.0 * scale));
        } else {
            double x = centerX - metrics.width / 2.0;
            layouts.add(new TextLayout(line.text, false, metrics.fontSize, family, x, baseline, 0, 0));
        }
    }
    return layouts;
}

private static TextMetrics measureAndFit(String text, double maxWidth, String family, int baseSize) {
    int size = baseSize;
    FontMetrics metrics = fontMetrics(family, size);
    while (size > 10 && metrics.stringWidth(text) > maxWidth) {
        size -= 1;
        metrics = fontMetrics(family, size);
    }
    return new TextMetrics(size, metrics.stringWidth(text), metrics.getAscent(), metrics.getDescent());
}

private static FontMetrics fontMetrics(String family, int size) {
    Font font = new Font(family, Font.PLAIN, size);
    METRIC_GRAPHICS.setFont(font);
    return METRIC_GRAPHICS.getFontMetrics(font);
}

private static String cdata(String text) {
    return "<![CDATA[" + text.replace("]]>", "]]]]><![CDATA[>") + "]]>";
}

private static String escapeAttr(String text) {
    return text.replace("&", "&amp;")
            .replace("'", "&apos;")
            .replace("\"", "&quot;")
            .replace("<", "&lt;")
            .replace(">", "&gt;");
}

private static void appendf(StringBuilder builder, String fmt, Object... args) {
    builder.append(String.format(Locale.US, fmt, args));
}

private static double pxX(int x, double scale) {
    return (x + PAD_X) * CELL_W * scale;
}

private static double pxY(int y, double scale) {
    return (y + PAD_Y) * CELL_H * scale;
}

private static ShapeGeometry buildGeometry(DiagramShape shape, double scale, boolean fixedSlope) {
    double x0 = pxX(shape.x0, scale);
    double y0 = pxY(shape.y0, scale);
    double x1 = pxX(shape.x1, scale);
    double y1 = pxY(shape.y1, scale);
    double width = x1 - x0;
    double height = y1 - y0;
    double cx = (x0 + x1) / 2.0;
    double cy = (y0 + y1) / 2.0;

    switch (shape.kind) {
        case RECT:
            if (shape.rounded) {
                double r = 5.0 * scale;
                Path2D.Double rounded = new Path2D.Double();
                rounded.moveTo(x0 + r, y0);
                rounded.lineTo(x1 - r, y0);
                rounded.quadTo(x1, y0, x1, y0 + r);
                rounded.lineTo(x1, y1 - r);
                rounded.quadTo(x1, y1, x1 - r, y1);
                rounded.lineTo(x0 + r, y1);
                rounded.quadTo(x0, y1, x0, y1 - r);
                rounded.lineTo(x0, y0 + r);
                rounded.quadTo(x0, y0, x0 + r, y0);
                rounded.closePath();
                String svg = String.format(
                        Locale.US,
                        "M%.1f %.1f L%.1f %.1f Q%.1f %.1f %.1f %.1f L%.1f %.1f Q%.1f %.1f %.1f %.1f L%.1f %.1f Q%.1f %.1f %.1f %.1f L%.1f %.1f Q%.1f %.1f %.1f %.1f z",
                        x0 + r, y0, x1 - r, y0, x1, y0, x1, y0 + r, x1, y1 - r, x1, y1, x1 - r, y1,
                        x0 + r, y1, x0, y1, x0, y1 - r, x0, y0 + r, x0, y0, x0 + r, y0);
                return new ShapeGeometry(rounded, svg, rounded);
            }
            Rectangle2D.Double rect = new Rectangle2D.Double(x0, y0, width, height);
            String rectSvg = String.format(
                    Locale.US,
                    "M%.1f %.1f L%.1f %.1f L%.1f %.1f L%.1f %.1f z",
                    x0, y0, x1, y0, x1, y1, x0, y1);
            return new ShapeGeometry(rect, rectSvg, rect);
        case DOCUMENT:
            double dx = width / 6.0;
            double wave = 8.0 * scale;
            Path2D.Double document = new Path2D.Double();
            document.moveTo(x0, y0);
            document.lineTo(x1, y0);
            document.lineTo(x1, y1);
            document.quadTo(cx + dx, y1 - wave, cx, y1);
            document.quadTo(cx - dx, y1 + wave, x0, y1);
            document.closePath();
            String documentSvg = String.format(
                    Locale.US,
                    "M%.1f %.1f L%.1f %.1f L%.1f %.1f Q%.1f %.1f %.1f %.1f Q%.1f %.1f %.1f %.1f z",
                    x0, y0, x1, y0, x1, y1, cx + dx, y1 - wave, cx, y1, cx - dx, y1 + wave, x0, y1);
            return new ShapeGeometry(document, documentSvg, document);
        case ELLIPSE:
            Ellipse2D.Double ellipse = new Ellipse2D.Double(x0, y0, width, height);
            double rx = width / 2.0;
            double ry = height / 2.0;
            double k = 0.5522847;
            String ellipseSvg = String.format(
                    Locale.US,
                    "M%.1f %.1f C%.5f %.1f %.1f %.5f %.1f %.1f C%.1f %.5f %.5f %.1f %.1f %.1f C%.5f %.1f %.1f %.5f %.1f %.1f C%.1f %.5f %.5f %.1f %.1f %.1f z",
                    cx, y0, cx + rx * k, y0, x1, cy - ry * k, x1, cy, x1, cy + ry * k, cx + rx * k, y1,
                    cx, y1, cx - rx * k, y1, x0, cy + ry * k, x0, cy, x0, cy - ry * k, cx - rx * k, y0,
                    cx, y0);
            return new ShapeGeometry(ellipse, ellipseSvg, ellipse);
        case DECISION:
            Path2D.Double diamond = new Path2D.Double();
            diamond.moveTo(x0, cy);
            diamond.lineTo(cx, y0);
            diamond.lineTo(x1, cy);
            diamond.lineTo(cx, y1);
            diamond.closePath();
            String diamondSvg = String.format(
                    Locale.US,
                    "M%.1f %.1f L%.1f %.1f L%.1f %.1f L%.1f %.1f z",
                    x0, cy, cx, y0, x1, cy, cx, y1);
            return new ShapeGeometry(diamond, diamondSvg, diamond);
        case MANUAL_OPERATION: {
            double slope = 10.0 * scale;
            Path2D.Double manual = new Path2D.Double();
            manual.moveTo(x0 - slope / 2.0, y0);
            manual.lineTo(x1 + slope / 2.0, y0);
            manual.lineTo(x1 - slope / 2.0, y1);
            manual.lineTo(x0 + slope / 2.0, y1);
            manual.closePath();
            String manualSvg = String.format(
                    Locale.US,
                    "M%.1f %.1f L%.1f %.1f L%.1f %.1f L%.1f %.1f z",
                    x0 - slope / 2.0, y0, x1 + slope / 2.0, y0, x1 - slope / 2.0, y1, x0 + slope / 2.0, y1);
            return new ShapeGeometry(manual, manualSvg, manual);
        }
        case TRAPEZOID: {
            double slope = fixedSlope ? 10.0 * scale : 10.0 * scale;
            Path2D.Double trapezoid = new Path2D.Double();
            trapezoid.moveTo(x0 + slope / 2.0, y0);
            trapezoid.lineTo(x1 - slope / 2.0, y0);
            trapezoid.lineTo(x1 + slope / 2.0, y1);
            trapezoid.lineTo(x0 - slope / 2.0, y1);
            trapezoid.closePath();
            String trapezoidSvg = String.format(
                    Locale.US,
                    "M%.1f %.1f L%.1f %.1f L%.1f %.1f L%.1f %.1f z",
                    x0 + slope / 2.0, y0, x1 - slope / 2.0, y0, x1 + slope / 2.0, y1, x0 - slope / 2.0, y1);
            return new ShapeGeometry(trapezoid, trapezoidSvg, trapezoid);
        }
        case IO: {
            double slope = fixedSlope ? 10.0 * scale : 10.0 * scale;
            Path2D.Double io = new Path2D.Double();
            io.moveTo(x0 + slope / 2.0, y0);
            io.lineTo(x1 + slope / 2.0, y0);
            io.lineTo(x1 - slope / 2.0, y1);
            io.lineTo(x0 - slope / 2.0, y1);
            io.closePath();
            String ioSvg = String.format(
                    Locale.US,
                    "M%.1f %.1f L%.1f %.1f L%.1f %.1f L%.1f %.1f z",
                    x0 + slope / 2.0, y0, x1 + slope / 2.0, y0, x1 - slope / 2.0, y1, x0 - slope / 2.0, y1);
            return new ShapeGeometry(io, ioSvg, io);
        }
        case STORAGE:
            return buildStorageGeometry(x0, y0, x1, y1, width, scale);
        default:
            throw new IllegalStateException();
    }
}

private static ShapeGeometry buildStorageGeometry(double x0, double y0, double x1, double y1, double width, double scale) {
    double top = 7.0 * scale;
    double bottom = 10.0 * scale;
    double inset = width / 6.0;
    Path2D.Double outline = new Path2D.Double();
    outline.moveTo(x0, y0);
    outline.curveTo(x0 + inset, y0 + top, x1 - inset, y0 + top, x1, y0);
    outline.curveTo(x1 - inset, y0 - top, x0 + inset, y0 - top, x0, y0);
    outline.moveTo(x0, y0);
    outline.lineTo(x0, y1);
    outline.curveTo(x0 + inset, y1 + bottom, x1 - inset, y1 + bottom, x1, y1);
    outline.lineTo(x1, y0);

    Path2D.Double shadow = new Path2D.Double();
    shadow.moveTo(x0, y0);
    shadow.curveTo(x0 + inset, y0 - top, x1 - inset, y0 - top, x1, y0);
    shadow.lineTo(x1, y1);
    shadow.curveTo(x1 - inset, y1 + bottom, x0 + inset, y1 + bottom, x0, y1);
    shadow.closePath();

    String svg = String.format(
            Locale.US,
            "M%.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f M%.1f %.1f L%.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f L%.1f %.1f ",
            x0, y0, x0 + inset, y0 + top, x1 - inset, y0 + top, x1, y0,
            x1 - inset, y0 - top, x0 + inset, y0 - top, x0, y0,
            x0, y0, x0, y1, x0 + inset, y1 + bottom, x1 - inset, y1 + bottom, x1, y1, x1, y0);
    return new ShapeGeometry(outline, svg, shadow);
}

private static void renderPng(Diagram diagram, CliOptions options, Path output) throws Exception {
    int width = (int) Math.round((diagram.width + 4.0) * CELL_W * options.scale);
    int height = (int) Math.round((diagram.height + 4.0) * CELL_H * options.scale);
    boolean alpha = options.transparent || options.background.a < 255;
    BufferedImage image = new BufferedImage(
            width,
            height,
            alpha ? BufferedImage.TYPE_INT_ARGB : BufferedImage.TYPE_INT_RGB);
    Graphics2D g = image.createGraphics();
    try {
        applyRenderingHints(g, options.noAntialias);
        if (!options.transparent) {
            g.setColor(options.background.toAwtColor());
            g.fillRect(0, 0, width, height);
        }
        if (options.debug) {
            drawDebugGrid(g, width, height, options.scale);
        }
        if (!options.noShadows) {
            drawShadows(image, diagram, options);
            g = image.createGraphics();
            applyRenderingHints(g, options.noAntialias);
        }
        for (Separation separation : diagram.separations) {
            g.setColor(java.awt.Color.WHITE);
            g.setStroke(new BasicStroke((float) (3.0 * options.scale), BasicStroke.CAP_SQUARE, BasicStroke.JOIN_MITER));
            if (separation.vertical) {
                g.draw(new Line2D.Double(
                        pxX(separation.coord, options.scale),
                        pxY(separation.start, options.scale),
                        pxX(separation.coord, options.scale),
                        pxY(separation.end, options.scale)));
            } else {
                g.draw(new Line2D.Double(
                        pxX(separation.start, options.scale),
                        pxY(separation.coord, options.scale),
                        pxX(separation.end, options.scale),
                        pxY(separation.coord, options.scale)));
            }
        }
        for (DiagramShape shape : diagram.shapes) {
            drawShape(g, shape, options);
        }
        for (StrokePathInfo path : diagram.paths) {
            drawPath(g, path, options);
        }
        for (GridPoint marker : diagram.markers) {
            drawMarker(g, marker, options.scale);
        }
        for (DiagramShape shape : diagram.shapes) {
            drawShapeText(g, shape, options);
        }
        for (LooseText text : diagram.looseTexts) {
            drawLooseText(g, text, options);
        }
    } finally {
        g.dispose();
    }
    String lower = output.getFileName().toString().toLowerCase(Locale.ROOT);
    ImageIO.write(image, lower.endsWith(".gif") ? "gif" : "png", output.toFile());
}

private static void applyRenderingHints(Graphics2D g, boolean noAntialias) {
    g.setRenderingHint(
            RenderingHints.KEY_ANTIALIASING,
            noAntialias ? RenderingHints.VALUE_ANTIALIAS_OFF : RenderingHints.VALUE_ANTIALIAS_ON);
    g.setRenderingHint(
            RenderingHints.KEY_TEXT_ANTIALIASING,
            noAntialias
                    ? RenderingHints.VALUE_TEXT_ANTIALIAS_OFF
                    : RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
    g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_NORMALIZE);
}

private static void drawDebugGrid(Graphics2D g, int width, int height, double scale) {
    g.setColor(new java.awt.Color(102, 102, 102));
    g.setStroke(new BasicStroke(0.5f));
    for (double x = 0; x <= width; x += CELL_W * scale) {
        g.draw(new Line2D.Double(x, 0, x, height));
    }
    for (double y = 0; y <= height; y += CELL_H * scale) {
        g.draw(new Line2D.Double(0, y, width, y));
    }
}

private static void drawShadows(BufferedImage target, Diagram diagram, CliOptions options) {
    BufferedImage shadow = new BufferedImage(target.getWidth(), target.getHeight(), BufferedImage.TYPE_INT_ARGB);
    Graphics2D g = shadow.createGraphics();
    try {
        applyRenderingHints(g, false);
        g.setComposite(AlphaComposite.SrcOver);
        g.setColor(new java.awt.Color(128, 128, 128, 180));
        AffineTransform shift = AffineTransform.getTranslateInstance(5.0 * options.scale, 5.0 * options.scale);
        for (DiagramShape shape : diagram.shapes) {
            ShapeGeometry geometry = buildGeometry(shape, options.scale, options.fixedSlope);
            Shape shadowShape = shift.createTransformedShape(geometry.shadowShape);
            g.fill(shadowShape);
        }
    } finally {
        g.dispose();
    }
    shadow = blur(shadow);
    Graphics2D onto = target.createGraphics();
    try {
        onto.drawImage(shadow, 0, 0, null);
    } finally {
        onto.dispose();
    }
}

private static BufferedImage blur(BufferedImage image) {
    float[] kernel = new float[25];
    Arrays.fill(kernel, 1.0f / 25.0f);
    ConvolveOp op = new ConvolveOp(new Kernel(5, 5, kernel), ConvolveOp.EDGE_NO_OP, null);
    BufferedImage first = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
    op.filter(image, first);
    BufferedImage second = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
    op.filter(first, second);
    return second;
}

private static void drawShape(Graphics2D g, DiagramShape shape, CliOptions options) {
    ShapeGeometry geometry = buildGeometry(shape, options.scale, options.fixedSlope);
    if (shape.kind == ShapeKind.STORAGE) {
        drawStorage(g, shape, geometry, options.scale);
        return;
    }
    g.setColor(shape.fill.toAwtColor());
    g.fill(geometry.fillShape);
    g.setColor(java.awt.Color.BLACK);
    g.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
    g.draw(geometry.fillShape);
}

private static void drawStorage(Graphics2D g, DiagramShape shape, ShapeGeometry geometry, double scale) {
    double x0 = pxX(shape.x0, scale);
    double y0 = pxY(shape.y0, scale);
    double x1 = pxX(shape.x1, scale);
    double y1 = pxY(shape.y1, scale);
    double width = x1 - x0;
    double inset = width / 6.0;
    double top = 7.0 * scale;
    double bottom = 10.0 * scale;

    g.setColor(shape.fill.toAwtColor());
    g.fill(new Rectangle2D.Double(x0, y0, width, y1 - y0));
    g.fill(new Ellipse2D.Double(x0, y0 - top, width, top * 2.0));
    g.fill(new Ellipse2D.Double(x0, y1 - bottom, width, bottom * 2.0));

    g.setColor(java.awt.Color.BLACK);
    g.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
    g.draw(new Arc2D.Double(x0, y0 - top, width, top * 2.0, 0, 360, Arc2D.OPEN));
    g.draw(new Line2D.Double(x0, y0, x0, y1));
    g.draw(new Line2D.Double(x1, y0, x1, y1));
    Path2D.Double bottomArc = new Path2D.Double();
    bottomArc.moveTo(x0, y1);
    bottomArc.curveTo(x0 + inset, y1 + bottom, x1 - inset, y1 + bottom, x1, y1);
    g.draw(bottomArc);
    g.draw(geometry.shadowShape);
}

private static void drawPath(Graphics2D g, StrokePathInfo path, CliOptions options) {
    if (path.points.size() < 2) {
        return;
    }
    Path2D.Double awtPath = new Path2D.Double();
    for (int i = 0; i < path.points.size(); i++) {
        GridPoint point = path.points.get(i);
        double x = pxX(point.x, options.scale);
        double y = pxY(point.y, options.scale);
        if (i == 0) {
            awtPath.moveTo(x, y);
        } else {
            awtPath.lineTo(x, y);
        }
    }
    g.setColor(java.awt.Color.BLACK);
    if (path.dashed) {
        g.setStroke(new BasicStroke(
                1.0f,
                BasicStroke.CAP_BUTT,
                BasicStroke.JOIN_ROUND,
                0,
                new float[] {5.0f, 5.0f},
                0));
    } else {
        g.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
    }
    g.draw(awtPath);
    if (path.arrowStart != null) {
        drawArrow(g, path.points.get(0), path.arrowStart, options.scale);
    }
    if (path.arrowEnd != null) {
        drawArrow(g, path.points.get(path.points.size() - 1), path.arrowEnd, options.scale);
    }
}

private static void drawArrow(Graphics2D g, GridPoint point, ArrowDir dir, double scale) {
    double x = pxX(point.x, scale);
    double y = pxY(point.y, scale);
    double[] c = arrowCoords(x, y, dir, scale);
    Path2D.Double triangle = new Path2D.Double();
    triangle.moveTo(c[0], c[1]);
    triangle.lineTo(c[2], c[3]);
    triangle.lineTo(c[4], c[5]);
    triangle.closePath();
    g.setColor(java.awt.Color.BLACK);
    g.fill(triangle);
}

private static double[] arrowCoords(double x, double y, ArrowDir dir, double scale) {
    switch (dir) {
        case RIGHT:
            return new double[] {x + 5.0 * scale, y, x - 5.0 * scale, y - 7.0 * scale, x - 5.0 * scale,
                    y + 7.0 * scale};
        case LEFT:
            return new double[] {x - 5.0 * scale, y, x + 5.0 * scale, y - 7.0 * scale, x + 5.0 * scale,
                    y + 7.0 * scale};
        case UP:
            return new double[] {x, y - 7.0 * scale, x - 5.0 * scale, y + 7.0 * scale, x + 5.0 * scale,
                    y + 7.0 * scale};
        case DOWN:
            return new double[] {x, y + 7.0 * scale, x - 5.0 * scale, y - 7.0 * scale, x + 5.0 * scale,
                    y - 7.0 * scale};
        default:
            throw new IllegalStateException();
    }
}

private static void drawMarker(Graphics2D g, GridPoint point, double scale) {
    double r = 4.0 * scale;
    double x = pxX(point.x, scale) - r;
    double y = pxY(point.y, scale) - r;
    Ellipse2D.Double marker = new Ellipse2D.Double(x, y, r * 2.0, r * 2.0);
    g.setColor(java.awt.Color.WHITE);
    g.fill(marker);
    g.setColor(java.awt.Color.BLACK);
    g.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
    g.draw(marker);
}

private static void drawShapeText(Graphics2D g, DiagramShape shape, CliOptions options) {
    String family = options.svgFontUrl != null ? "Courier" : "Courier";
    for (TextLayout layout : layoutShapeText(shape, options.scale, family)) {
        Font font = new Font(family, Font.PLAIN, layout.fontSize);
        g.setFont(font);
        g.setColor(shape.textColor.toAwtColor());
        if (layout.bullet) {
            double d = layout.bulletRadius * 2.0;
            g.fill(new Ellipse2D.Double(layout.bulletX - layout.bulletRadius,
                    layout.baseline - layout.bulletRadius * 0.8, d, d));
        }
        g.drawString(layout.text, (float) layout.x, (float) layout.baseline);
    }
}

private static void drawLooseText(Graphics2D g, LooseText text, CliOptions options) {
    String family = "Courier";
    TextMetrics metrics = measureAndFit(
            text.text,
            pxX(text.end, options.scale) - pxX(text.start, options.scale),
            family,
            BASE_FONT_SIZE);
    double centerX = (pxX(text.start, options.scale) + pxX(text.end, options.scale)) / 2.0;
    double x = centerX - metrics.width / 2.0;
    double baseline = pxY(text.row, options.scale) + metrics.baselineOffset();
    g.setFont(new Font(family, Font.PLAIN, metrics.fontSize));
    g.setColor(java.awt.Color.BLACK);
    g.drawString(text.text, (float) x, (float) baseline);
}

